unsafe fn tdefl_compress_lz_codes(mut d: *mut tdefl_compressor) -> mz_bool {
    // SAFETY: Caller provides a valid, unique pointer to tdefl_compressor for the duration
    // of this function, matching the original function's contract.
    let d_view: &mut tdefl_compressor = unsafe { &mut *d };

    let mut flags: mz_uint = 1;
    let mut p_lz_codes: *mut mz_uint8 = d_view.m_lz_code_buf.as_mut_ptr();

    let litlen_codes = &d_view.m_huff_codes[0];
    let litlen_sizes = &d_view.m_huff_code_sizes[0];
    let dist_codes = &d_view.m_huff_codes[1];
    let dist_sizes = &d_view.m_huff_code_sizes[1];

    let mut bit_buffer = d_view.m_bit_buffer;
    let mut bits_in = d_view.m_bits_in;
    let mut out_ptr = d_view.m_pOutput_buf;
    let out_end = d_view.m_pOutput_buf_end;
    let lz_end = d_view.m_pLZ_code_buf;

    #[inline(always)]
    unsafe fn put_bits(
        bit_buffer: &mut mz_uint,
        bits_in: &mut mz_uint,
        out_ptr: &mut *mut mz_uint8,
        out_end: *mut mz_uint8,
        bits: mz_uint,
        len: mz_uint,
    ) {
        *bit_buffer |= bits << *bits_in;
        *bits_in = bits_in.wrapping_add(len);
        while *bits_in >= 8 {
            if *out_ptr < out_end {
                let p = *out_ptr;
                // SAFETY: p is checked to be within the writable output buffer before write,
                // and then advanced by exactly one byte.
                unsafe {
                    *p = *bit_buffer as mz_uint8;
                }
                // SAFETY: Advancing by one stays within or one-past the output buffer because
                // the pointer was strictly less than out_end.
                *out_ptr = unsafe { p.add(1) };
            }
            *bit_buffer >>= 8;
            *bits_in = bits_in.wrapping_sub(8);
        }
    }

    while p_lz_codes < lz_end {
        if flags == 1 {
            let fresh = p_lz_codes;
            // SAFETY: p_lz_codes < lz_end, so reading one byte and advancing by one is valid.
            flags = (unsafe { *fresh } as c_int | 0x100) as mz_uint;
            // SAFETY: See above; advancing by one byte remains within the encoded stream.
            p_lz_codes = unsafe { p_lz_codes.add(1) };
        }

        if flags & 1 != 0 {
            // SAFETY: Match entries consume 3 bytes and the original code assumes the stream is valid.
            let match_len = unsafe { *p_lz_codes.add(0) as mz_uint };
            // SAFETY: See above; bytes 1 and 2 are part of the same valid 3-byte match entry.
            let match_dist = (unsafe { *p_lz_codes.add(1) as c_int }
                | ((unsafe { *p_lz_codes.add(2) as c_int }) << 8)) as mz_uint;
            // SAFETY: Advancing by the 3-byte match entry size is valid for a valid encoded stream.
            p_lz_codes = unsafe { p_lz_codes.add(3) };

            let len_sym = s_tdefl_len_sym[match_len as usize] as usize;
            put_bits(
                &mut bit_buffer,
                &mut bits_in,
                &mut out_ptr,
                out_end,
                litlen_codes[len_sym] as mz_uint,
                litlen_sizes[len_sym] as mz_uint,
            );

            let len_extra = s_tdefl_len_extra[match_len as usize] as mz_uint;
            put_bits(
                &mut bit_buffer,
                &mut bits_in,
                &mut out_ptr,
                out_end,
                match_len & mz_bitmasks[len_extra as usize],
                len_extra,
            );

            let (sym, num_extra_bits) = if match_dist < 512 {
                (
                    s_tdefl_small_dist_sym[match_dist as usize] as mz_uint,
                    s_tdefl_small_dist_extra[match_dist as usize] as mz_uint,
                )
            } else {
                let idx = (match_dist >> 8) as usize;
                (
                    s_tdefl_large_dist_sym[idx] as mz_uint,
                    s_tdefl_large_dist_extra[idx] as mz_uint,
                )
            };

            let sym_usize = sym as usize;
            put_bits(
                &mut bit_buffer,
                &mut bits_in,
                &mut out_ptr,
                out_end,
                dist_codes[sym_usize] as mz_uint,
                dist_sizes[sym_usize] as mz_uint,
            );

            put_bits(
                &mut bit_buffer,
                &mut bits_in,
                &mut out_ptr,
                out_end,
                match_dist & mz_bitmasks[num_extra_bits as usize],
                num_extra_bits,
            );
        } else {
            let fresh = p_lz_codes;
            // SAFETY: Literal entries consume 1 byte and p_lz_codes < lz_end here.
            let lit = unsafe { *fresh as mz_uint };
            // SAFETY: Advancing by one byte after consuming the literal is valid.
            p_lz_codes = unsafe { p_lz_codes.add(1) };

            let lit_usize = lit as usize;
            put_bits(
                &mut bit_buffer,
                &mut bits_in,
                &mut out_ptr,
                out_end,
                litlen_codes[lit_usize] as mz_uint,
                litlen_sizes[lit_usize] as mz_uint,
            );
        }

        flags >>= 1;
    }

    put_bits(
        &mut bit_buffer,
        &mut bits_in,
        &mut out_ptr,
        out_end,
        litlen_codes[256] as mz_uint,
        litlen_sizes[256] as mz_uint,
    );

    d_view.m_bit_buffer = bit_buffer;
    d_view.m_bits_in = bits_in;
    d_view.m_pOutput_buf = out_ptr;

    (out_ptr < out_end) as c_int
}

